insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006702', '$1/11$', 'Os módulos decrescem para zero, satisfazendo as hipóteses do teorema do resto. O erro é no máximo o módulo do primeiro termo omitido: $1/(10+1)=1/11$.') on conflict do nothing;
