insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006703', '$9$', 'A cota é $1/(N+1)^2$. Exija $1/(N+1)^2\le1/100$. Temos $N+1\ge10$, logo $N\ge9$. Para $N=8$, a cota é $1/81>0{,}01$.') on conflict do nothing;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000067030', '40000000-0000-4000-8000-000000006703', 'Passo 1', 'A cota é $1/(N+1)^2$. Exija $1/(N+1)^2\le1/100$.', '1') on conflict do nothing;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000067031', '40000000-0000-4000-8000-000000006703', 'Passo 2', 'Temos $N+1\ge10$, logo $N\ge9$. Para $N=8$, a cota é $1/81>0{,}01$.', '2') on conflict do nothing;
